function evidence = f90_xmech08_extract_candidate_evidence(modelPath, outDir)
%f90_xmech08_extract_candidate_evidence Branch-safe candidate extraction entry.
arguments
    modelPath (1,1) string
    outDir (1,1) string
end

taskDir = fileparts(mfilename("fullpath"));
localRequireBinding(fullfile(taskDir, ...
    "f90_xmech08_extract_evidence.m"), ...
    "present");
localRequireBinding(fullfile(taskDir, ...
    "f90_xmech08_structure_policy.json"), ...
    "present");

evidence = f90_xmech08_extract_evidence(modelPath, outDir);
assert(isfield(evidence, "candidate_evidence_ready") && ...
    logical(evidence.candidate_evidence_ready), ...
    "SimuVerity:F90:XMECH08:EvidenceContract", ...
    "Candidate evaluator did not return candidate CRITERIA_SCORER evidence.");
assert(isfield(evidence, "current_evidence_reusable_as") && ...
    ~logical(evidence.current_evidence_reusable_as), ...
    "SimuVerity:F90:XMECH08:HistoricalEvidenceBoundary", ...
    "Historical CURRENT_GROUPS evidence cannot be relabeled as CRITERIA_SCORER evidence.");
assert(isfield(evidence, "extraction_only") && ...
    logical(evidence.extraction_only) && ...
    isfield(evidence, "score_fields_present") && ...
    ~logical(evidence.score_fields_present), ...
    "SimuVerity:F90:XMECH08:ExtractionOnly", ...
    "Candidate evaluator must not aggregate score fields.");
assert(isfield(evidence, "candidate_binding_preserved_by_current_audit") && ...
    logical(evidence.candidate_binding_preserved_by_current_audit), ...
    "SimuVerity:F90:XMECH08:CandidateBinding", ...
    "The CRITERIA_SCORER audit must preserve the sealed candidate binding.");
assert(isfield(evidence.static_audit, ...
    "physical_port_line_reverse_grouping") && ...
    logical(evidence.static_audit.physical_port_line_reverse_grouping), ...
    "SimuVerity:F90:XMECH08:ReverseGrouping", ...
    "The CRITERIA_SCORER endpoint recovery flag is missing.");
evidencePath = fullfile(outDir, "evidence.json");
assert(isfile(evidencePath), "SimuVerity:F90:XMECH08:EvidenceMissing", ...
    "Evidence extractor did not write evidence.json.");
end

function localRequireBinding(pathValue, expectedFilePresence)
assert(isfile(pathValue) && ...
    localFilePresence(pathValue) == lower(string(expectedFilePresence)), ...
    "SimuVerity:F90:XMECH08:DependencyBinding", ...
    "A declared CRITERIA_SCORER evaluator dependency is missing or changed.");
end

function binding = localFilePresence(pathValue)
assert(isfile(pathValue), "SimuVerity:FileMissing", "Required file is missing: %s", pathValue);
binding = "present";
end

